<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio Business OS V14.12 — Executive Expense, Overhead & Operating View */
function tuff_beatz_v1412_categories(){return array('software'=>'Software / Subscriptions','hosting'=>'Hosting / Infrastructure','marketing'=>'Marketing / Promotion','insurance'=>'Insurance','legal'=>'Legal / Accounting','office'=>'Office / Administration','equipment'=>'Equipment / Maintenance','utilities'=>'Utilities / Communications','travel'=>'Business Travel','payroll'=>'Payroll / Owner Compensation','other'=>'Other Overhead');}
function tuff_beatz_v1412_month_key($year=0,$month=0){$year=$year?: (int)current_time('Y');$month=$month?: (int)current_time('n');return sprintf('%04d-%02d',$year,$month);}
function tuff_beatz_v1412_overhead($year=0,$month=0){$key=tuff_beatz_v1412_month_key($year,$month);$raw=get_option('_tb_v1412_overhead_'.$key,array());if(!is_array($raw))$raw=array();$items=array();$total=0.0;foreach(tuff_beatz_v1412_categories() as $k=>$label){$v=max(0,(float)($raw['items'][$k]??0));$items[$k]=$v;$total+=$v;}return array('month'=>$key,'items'=>$items,'notes'=>(string)($raw['notes']??''),'updated_at'=>(string)($raw['updated_at']??''),'updated_by'=>(int)($raw['updated_by']??0),'total'=>round($total,2),'recorded'=>!empty($raw));}
function tuff_beatz_v1412_save_overhead(){if(!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())wp_die('Unauthorized',403);check_admin_referer('tb_v1412_save','tb_v1412_nonce');$month=sanitize_text_field(wp_unslash($_POST['overhead_month']??''));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=tuff_beatz_v1412_month_key();$raw=is_array($_POST['overhead']??null)?wp_unslash($_POST['overhead']):array();$items=array();foreach(tuff_beatz_v1412_categories() as $k=>$label)$items[$k]=max(0,(float)($raw[$k]??0));update_option('_tb_v1412_overhead_'.$month,array('items'=>$items,'notes'=>sanitize_textarea_field(wp_unslash($_POST['overhead_notes']??'')),'updated_at'=>current_time('mysql'),'updated_by'=>get_current_user_id()),false);wp_safe_redirect(add_query_arg(array('overhead_saved'=>'1','overhead_month'=>$month),home_url('/business-command/')));exit;}
add_action('admin_post_tb_v1412_save_overhead','tuff_beatz_v1412_save_overhead');
function tuff_beatz_v1412_operating_view(){
 $year=(int)current_time('Y');$month=(int)current_time('n');$over=tuff_beatz_v1412_overhead($year,$month);$collected=function_exists('tuff_beatz_v1410_monthly_collected')?tuff_beatz_v1410_monthly_collected($year,$month):0.0;$q=new WP_Query(array('post_type'=>'tb_request','post_status'=>'publish','posts_per_page'=>500,'fields'=>'ids'));$direct=0.0;$covered_paid=0.0;$covered=0;foreach($q->posts as $id){if(!function_exists('tuff_beatz_v1411_cost_basis'))break;$c=tuff_beatz_v1411_cost_basis($id);if(!$c['recorded'])continue;$payments=function_exists('tuff_beatz_payment_data')?tuff_beatz_payment_data($id):array();$month_paid=0.0;foreach($payments as $p){if(($p['status']??'')!=='paid'||empty($p['date']))continue;$ts=strtotime((string)$p['date']);if($ts&&(int)wp_date('Y',$ts)===$year&&(int)wp_date('n',$ts)===$month)$month_paid+=(float)($p['amount']??0);}if($month_paid<=0)continue;$covered++;$covered_paid+=$month_paid;$direct+=(float)$c['total'];}
 $contribution=$covered_paid-$direct;$operating=$contribution-$over['total'];$margin=$covered_paid>0?($operating/$covered_paid)*100:null;$coverage=$collected>0?min(100,($covered_paid/$collected)*100):0;$break_even=$direct+$over['total'];return array('month_label'=>wp_date('F Y'),'month_key'=>tuff_beatz_v1412_month_key($year,$month),'collected'=>$collected,'covered_collected'=>$covered_paid,'direct_cost'=>$direct,'overhead'=>$over['total'],'contribution'=>$contribution,'operating_contribution'=>$operating,'operating_margin'=>$margin,'cost_coverage'=>$coverage,'covered_projects'=>$covered,'break_even_revenue'=>$break_even,'overhead_data'=>$over);
}
function tuff_beatz_v1412_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$x=tuff_beatz_v1412_operating_view();$money=function($n){return function_exists('tuff_beatz_money')?tuff_beatz_money($n):'$'.number_format((float)$n,2);};ob_start();?><section class="tb-v1412-overhead"><div class="tb-v1412-head"><div><small>OPERATING INTELLIGENCE • V14.12</small><h3><?php echo esc_html($x['month_label']);?> Operating View</h3><p>Combines monthly collected revenue, recorded project direct costs and producer-entered business overhead. This is an internal management view, not tax-accounting net income.</p></div><div><span>COST-COVERED COLLECTIONS</span><strong><?php echo esc_html(number_format((float)$x['cost_coverage'],0));?>%</strong></div></div><div class="tb-v1412-kpis"><article><small>MONTHLY COLLECTIONS</small><strong><?php echo esc_html($money($x['collected']));?></strong><span>All recorded paid transactions</span></article><article><small>COVERED COLLECTIONS</small><strong><?php echo esc_html($money($x['covered_collected']));?></strong><span>Payments tied to projects with cost basis</span></article><article><small>DIRECT PROJECT COST</small><strong><?php echo esc_html($money($x['direct_cost']));?></strong><span>Recorded V14.11 cost basis</span></article><article><small>MONTHLY OVERHEAD</small><strong><?php echo esc_html($money($x['overhead']));?></strong><span>Business-wide expenses entered below</span></article><article><small>OPERATING CONTRIBUTION</small><strong><?php echo esc_html($money($x['operating_contribution']));?></strong><span>Covered collections − direct costs − overhead</span></article><article><small>OPERATING MARGIN</small><strong><?php echo $x['operating_margin']===null?'—':esc_html(number_format((float)$x['operating_margin'],1).'%');?></strong><span>Management estimate, not tax net income</span></article></div><details class="tb-v1412-entry"><summary>Enter <?php echo esc_html($x['month_label']);?> Overhead</summary><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tb_v1412_save_overhead"><input type="hidden" name="overhead_month" value="<?php echo esc_attr($x['month_key']);?>"><?php wp_nonce_field('tb_v1412_save','tb_v1412_nonce');?><div class="tb-v1412-fields"><?php foreach(tuff_beatz_v1412_categories() as $k=>$label):?><label><?php echo esc_html($label);?><input type="number" min="0" step="0.01" name="overhead[<?php echo esc_attr($k);?>]" value="<?php echo esc_attr((string)($x['overhead_data']['items'][$k]??0));?>"></label><?php endforeach;?></div><label class="tb-v1412-notes">Notes<textarea name="overhead_notes"><?php echo esc_textarea($x['overhead_data']['notes']);?></textarea></label><button type="submit">Save Monthly Overhead</button></form></details><div class="tb-v1412-note"><strong>Break-even reference: <?php echo esc_html($money($x['break_even_revenue']));?></strong><span>Based only on direct costs represented in covered collections plus entered monthly overhead. Because project cost basis is not time-accrued, this should be used as management intelligence rather than formal accounting.</span></div></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var anchor=document.querySelector('.tb-v1411-profit')||document.querySelector('.tb-v1410-forecast')||document.querySelector('.tb-v149-intel');if(!anchor||document.querySelector('.tb-v1412-overhead'))return;var box=document.createElement('div');box.innerHTML=<?php echo wp_json_encode($html);?>;anchor.insertAdjacentElement('afterend',box.firstElementChild);var eye=document.querySelector('.tb-biz-hero .eyebrow');if(eye)eye.textContent='TUFF BEATZ • STUDIO BUSINESS OS V14.12';});</script><?php }
add_action('wp_footer','tuff_beatz_v1412_panel',12);
function tuff_beatz_v1412_css(){if(!is_page('business-command'))return;wp_add_inline_style('tuff-beatz-business-command','.tb-v1412-overhead{margin-top:18px;padding:20px;border:1px solid rgba(216,180,90,.13);border-radius:18px;background:#0b0b0b}.tb-v1412-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-end;padding-bottom:16px;border-bottom:1px solid rgba(255,255,255,.05)}.tb-v1412-head small,.tb-v1412-kpis small{display:block;color:#8f7744;font-size:.52rem;letter-spacing:.13em}.tb-v1412-head h3{margin:4px 0;color:#dfd6c2;font-family:Cinzel,serif}.tb-v1412-head p{margin:5px 0 0;max-width:720px;color:#716a5e;font-size:.6rem;line-height:1.5}.tb-v1412-head>div:last-child{text-align:right}.tb-v1412-head span,.tb-v1412-head strong{display:block}.tb-v1412-head span{color:#716a5e;font-size:.5rem;letter-spacing:.1em}.tb-v1412-head strong{margin-top:4px;color:#e3c66d;font:1.5rem Cinzel,serif}.tb-v1412-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.tb-v1412-kpis article{padding:14px;border:1px solid rgba(255,255,255,.05);border-radius:13px;background:rgba(255,255,255,.014)}.tb-v1412-kpis strong,.tb-v1412-kpis span{display:block}.tb-v1412-kpis strong{margin:7px 0 3px;color:#e2c66c;font-family:Cinzel,serif}.tb-v1412-kpis span{color:#6e675d;font-size:.55rem}.tb-v1412-entry{margin-top:10px;padding:14px;border:1px solid rgba(255,255,255,.05);border-radius:14px;background:rgba(255,255,255,.012)}.tb-v1412-entry summary{cursor:pointer;color:#d8b95d;font-size:.65rem;font-weight:700;letter-spacing:.06em}.tb-v1412-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.tb-v1412-fields label,.tb-v1412-notes{color:#7d7568;font-size:.55rem}.tb-v1412-fields input,.tb-v1412-notes textarea{display:block;width:100%;margin-top:5px;border:1px solid rgba(255,255,255,.08);border-radius:9px;background:#080808;color:#ddd2bc;padding:9px}.tb-v1412-notes{display:block;margin-top:10px}.tb-v1412-notes textarea{min-height:64px}.tb-v1412-entry button{margin-top:10px;padding:10px 14px;border:1px solid rgba(216,180,90,.24);border-radius:9px;background:rgba(216,180,90,.05);color:#d8b95d;cursor:pointer}.tb-v1412-note{display:flex;justify-content:space-between;gap:20px;margin-top:10px;padding:13px;border:1px solid rgba(216,180,90,.08);border-radius:12px}.tb-v1412-note strong{color:#d7c18a;font-size:.65rem}.tb-v1412-note span{max-width:680px;color:#6f685e;font-size:.54rem;line-height:1.5}@media(max-width:900px){.tb-v1412-kpis,.tb-v1412-fields{grid-template-columns:repeat(2,1fr)}.tb-v1412-head,.tb-v1412-note{align-items:flex-start;flex-direction:column}.tb-v1412-head>div:last-child{text-align:left}}@media(max-width:620px){.tb-v1412-kpis,.tb-v1412-fields{grid-template-columns:1fr}}');}
add_action('wp_enqueue_scripts','tuff_beatz_v1412_css',108);
